import { APIError } from 'payload';
/** Deletes the object at `storageFilePath`. Payload resolves the complete path. */ export const getDeleteFile = ({ client })=>{
    return async ({ collection, storageFilePath })=>{
        const { error, response } = await client.DELETE('/api/v0/uploads/{collectionId}/{filename}', {
            params: {
                path: {
                    collectionId: collection.slug,
                    filename: storageFilePath
                }
            }
        });
        if (error || !response.ok) {
            throw new APIError(`Failed to delete file: ${error?.message ?? response.statusText}`, response.status, {
                code: error?.code
            });
        }
    };
};
